import type { EngineInterface, Register, Timer } from 'claude-code'

import { alertDrop, lossChart } from './bridge'
import type { PaceJob, PaceJobs } from './bridge'
import { chartSvg, ema, PALETTE } from './chart'
import { cut, dropFrom, fmtDur, isAway, latestUserAt, MAX_FILE_BYTES, nextPurge, OP_LINE, opFrom, presenceWith, routeFor, TOOL } from './drop'
import type { Drop, Field, Kind, Route } from './drop'
import { attachments, baseOf, card, curlConfig, failure, messageUrl, parseCurl, patchArgv, payload, postArgv, postUrl, STRINGS, tookField } from './embed'
import type { Lang, Strings } from './embed'

type Raw = Record<string, unknown>
type Sent = { ok: boolean; message: string; id?: string }

// what a `: drop` call reads back, in the Bash tool's own shape
const shell = (stdout: string) => ({ result: { stdout, stderr: '', interrupted: false } })
const URL_RE = /https?:\/\/\S+/g
const MONTHS: Record<Lang, string[]> = {
  es: ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'],
  en: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'],
}
const KEEP_SESSIONS = 30
// turns the safety net speaks for: the user's own, and background work they started finishing; not
// another plugin's message (a pace-line alert already has its card)
const NET_ORIGINS = new Set(['composer', 'bridge', 'task-notification', 'auto-continuation'])

const rules = (awayMinutes: number) => `# Discord cards (discord-drop)
The user reads Discord on their phone. A card reaches them only when they're away (no message from them to this session for ${awayMinutes} min) or when they asked for one; while they're working with you nothing is sent. Send a card with ${TOOL}; it runs nothing and needs no permission. The mod answers "sent", "progress updated", or "held" (they're here: don't mention it).
- Starting something that will take a while (a download, a long change, a training or eval run, a batch of figures): say once, in the user's language, that if they're away when it finishes you'll message them on Discord.
- When it finishes, one drop: kind "result" for numbers or figures, "done" otherwise, "urgent" for a failure that needs them, "needs-you" when you stopped to ask. Result first, in the user's language, one phone screen: what finished; key numbers in fields (metric | baseline | Δ); the PR or run link as url; what they need to decide. The main plot as image, other files (≤10, ≤10 MB each) in files, absolute paths.
- Long work you can follow: kind "progress" with a key, progress 0-1 and eta (unix seconds); the same key edits the same card without a sound; final:true closes it and announces the end.
- "force": true only when the user asked to be messaged.
- pace-line's batch-job alerts already reach Discord through this mod: drop about a job only to add something (a diagnosis and a fix).
- Never write the webhook URL in a command. The discord-drop skill has card templates (eval, paper figures, sweeps, datasets, reproducibility).
: drop <<'EOF'
{"kind":"result","title":"Eval COCO val2017","text":"mAP 43.0, +1.8 over the baseline","fields":[{"name":"mAP","value":"43.0"},{"name":"baseline","value":"41.2"},{"name":"Δ","value":"+1.8"}],"image":"/abs/path/pr_curve.png"}
EOF`

const handoffPrompt = (left: string, job: string | null) =>
  `[discord-drop: this allocation${job ? ` (Slurm job ${job})` : ''} ends in ${left} and the user is away; not typed by the user]
Send one \`: drop\` now with kind "urgent" and "force": true: what you were doing, where you left it (files, branch, uncommitted changes, running jobs) and how to pick it up in a new session. Then carry on if there is time.`

/** A Drop of the mod's own: every field not given left empty. */
const own = (d: Partial<Drop> & Pick<Drop, 'kind' | 'title'>): Drop => ({
  text: '', fields: [], image: null, files: [], url: null, key: null, progress: null, eta: null, final: false, force: false, author: null, footer: null, ...d,
})

/** What a waiting tool call is about, for the card. */
function describe(tool: string, input: unknown): string {
  const o = (input && typeof input === 'object' ? input : {}) as Raw
  if (tool === 'Bash' && typeof o.command === 'string') return `\`${tool}\`\n\`\`\`\n${cut(o.command, 900)}\n\`\`\``
  for (const k of ['file_path', 'path', 'url', 'notebook_path']) if (typeof o[k] === 'string') return `\`${tool}\` → \`${cut(o[k] as string, 300)}\``
  return `\`${tool}\`\n\`\`\`json\n${cut(JSON.stringify(o), 600)}\n\`\`\``
}

/** An AskUserQuestion's questions and options, numbered. */
function questionsText(input: unknown, s: Strings): string {
  const qs = Array.isArray((input as Raw | undefined)?.questions) ? ((input as Raw).questions as Raw[]) : []
  const out = qs.slice(0, 4).map(q => {
    const opts = Array.isArray(q.options) ? (q.options as Raw[]) : []
    const lines = opts.map((o, i) => `${i + 1}. **${String(o.label ?? '')}**${o.description ? ` — ${cut(String(o.description), 140)}` : ''}`)
    return [`**${cut(String(q.question ?? ''), 300)}**`, ...lines].join('\n')
  })
  return [...out, `-# ${s.answerInTerminal}`].join('\n\n')
}

// ── state: the settings, what this load read, what the session knows of the person ──

const cfg = {
  awayMinutes: 30,
  needsYouMinutes: 5,
  safetyNet: true,
  sessionEndMinutes: 30,
  purgeWarnDays: 3,
  lang: 'es' as Lang,
}
const S = () => STRINGS[cfg.lang]

const env = {
  user: '',
  host: 'host',
  project: null as string | null,
  sessionId: 'session',
  /** ~/.claude/discord-drop */
  dir: '',
  url: null as string | null,
  ownJob: null as string | null,
  endsAt: null as number | null,
  tzMinutes: 0,
}

/** Kept in the store, so a reload of the mod doesn't forget it. */
const st = {
  lastUserAt: null as number | null,
  lastSentAt: 0,
  safetyFired: false,
  bridgeAfter: 0,
  handoff: 'none' as 'none' | 'asked' | 'done',
  handoffAskedAt: 0,
}
let hasToldRules = false
let turnOrigin = ''
let lastAssistant = ''
let waiting: { timer: Timer; tool: string } | null = null

const sessionKey = () => `s:${env.sessionId}`

async function persist($: EngineInterface): Promise<void> {
  await $.store.set(sessionKey(), { ...st })
}

async function readText($: EngineInterface, path: string): Promise<string | null> {
  try {
    return await $.fs.read(path)
  } catch {
    return null
  }
}

async function readJson($: EngineInterface, path: string): Promise<unknown> {
  const text = await readText($, path)
  try {
    return text ? (JSON.parse(text) as unknown) : null
  } catch {
    return null
  }
}

async function exists($: EngineInterface, path: string): Promise<boolean> {
  try {
    return await $.fs.exists(path)
  } catch {
    return false
  }
}

/** The webhook: DISCORD_WEBHOOK_URL, else ~/.claude/discord-drop/webhook. */
async function webhook($: EngineInterface): Promise<string | null> {
  if (env.url) return env.url
  return env.dir ? (await readText($, `${env.dir}/webhook`))?.trim() || null : null
}

// ── talking to Discord ──

/** Runs curl against the webhook, the URL on stdin; one retry after a rate limit. */
async function call($: EngineInterface, argv: string[], target: string): Promise<Sent> {
  for (let attempt = 0; attempt < 2; attempt++) {
    let r
    try {
      r = await $.process.run(argv, { stdin: curlConfig(target), timeoutMs: 90_000 })
    } catch (err) {
      return { ok: false, message: `discord-drop: curl did not run (${String(err).replace(URL_RE, '<url>').slice(0, 160)}).` }
    }
    const { status, body } = parseCurl(r.stdout)
    if (status >= 200 && status < 300) return { ok: true, message: 'drop: sent', id: typeof body?.id === 'string' ? body.id : undefined }
    if (status === 429 && attempt === 0) {
      const wait = Number(body?.retry_after)
      await $.clock.sleep(Math.min(10_000, (Number.isFinite(wait) ? wait : 1) * 1000))
      continue
    }
    return { ok: false, message: failure(status, body, r.stderr) }
  }
  return { ok: false, message: 'discord-drop: Discord kept rate-limiting the card.' }
}

/** Posts a card as a new message; `isSilent` lands it without a notification. */
async function post($: EngineInterface, drop: Drop, isSilent: boolean): Promise<Sent> {
  const url = await webhook($)
  if (!url) return { ok: false, message: 'discord-drop: no webhook. Set DISCORD_WEBHOOK_URL, or put the URL alone in ~/.claude/discord-drop/webhook (chmod 600).' }
  for (const p of [drop.image, ...drop.files]) {
    if (!p) continue
    let info
    try {
      info = await $.fs.stat(p)
    } catch {
      return { ok: false, message: `discord-drop: ${p} does not exist.` }
    }
    if (info.kind !== 'file') return { ok: false, message: `discord-drop: ${p} is not a file.` }
    if (info.size > MAX_FILE_BYTES) {
      return { ok: false, message: `discord-drop: ${p} is ${(info.size / 1048576).toFixed(1)} MB; Discord takes 10 MB per file. Shrink it (a smaller PNG, ffmpeg for video) and send again.` }
    }
  }
  const now = await $.clock.now()
  const ctx = { host: env.host, project: env.project, now, lang: cfg.lang }
  let a = attachments(drop)
  let built = card(drop, { ...ctx, image: a.image })
  if (built.isCut && env.dir) {
    // the text in full rides along as a file
    const full = `${env.dir}/out/${(drop.title || 'drop').replace(/[^A-Za-z0-9._-]+/g, '_').slice(0, 40)}-${now}.md`
    await $.fs.write(full, `# ${drop.title}\n\n${drop.text}\n`)
    a = attachments(drop, [full])
    built = card(drop, { ...ctx, image: a.image })
  }
  const uploads = [...(a.image ? [a.image] : []), ...a.files]
  const r = await call($, postArgv(payload(built.embed, uploads, isSilent), uploads), postUrl(baseOf(url)))
  return r.ok && isSilent ? { ...r, message: 'drop: sent (silent)' } : r
}

/** Rewrites a message the webhook sent: an edit makes no sound, whoever is looking. */
async function edit($: EngineInterface, id: string, drop: Drop): Promise<Sent> {
  const url = await webhook($)
  if (!url) return { ok: false, message: 'discord-drop: no webhook.' }
  const { embed } = card({ ...drop, image: null }, { host: env.host, project: env.project, now: await $.clock.now(), lang: cfg.lang, image: null })
  return call($, patchArgv(JSON.stringify({ embeds: [embed], allowed_mentions: { parse: [] } })), messageUrl(baseOf(url), id))
}

const held = (now: number) =>
  `drop: held. The user is here (last message ${st.lastUserAt === null ? '?' : fmtDur((now - st.lastUserAt) / 1000)} ago), so nothing was sent; tell them in the terminal instead.`

/** A progress card: created quietly when the user is away, edited in place, announced at the end. */
async function progress($: EngineInterface, drop: Drop, away: boolean, now: number): Promise<string> {
  const storeKey = `progress:${drop.key}`
  const saved = (await $.store.get(storeKey)) as { id?: string } | undefined
  if (drop.final) {
    if (saved?.id) await edit($, saved.id, { ...drop, progress: 1 })
    await $.store.delete(storeKey)
    const endKind: Kind = drop.fields.length || drop.image ? 'result' : 'done'
    if (routeFor(endKind, drop.force, away) === 'hold') return saved?.id ? 'drop: progress card closed; the user is here, so the end was not announced.' : held(now)
    const r = await post($, { ...drop, kind: endKind, progress: null, eta: null, key: null }, false)
    if (r.ok) {
      st.lastSentAt = now
      await persist($)
    }
    return r.ok ? 'drop: progress closed and the end announced' : r.message
  }
  if (saved?.id) {
    const r = await edit($, saved.id, drop)
    return r.ok ? 'drop: progress updated' : r.message
  }
  if (routeFor('progress', drop.force, away) === 'hold') return held(now)
  const r = await post($, drop, true)
  if (r.ok && r.id) await $.store.set(storeKey, { id: r.id, at: now })
  return r.ok ? 'drop: progress card created (silent); later drops with this key edit it' : r.message
}

/** Delivers a drop by the rule (or by the route given) and says what happened. */
async function send($: EngineInterface, drop: Drop, forced?: Route): Promise<string> {
  try {
    const now = await $.clock.now()
    const away = isAway(st.lastUserAt, now, cfg.awayMinutes)
    if (drop.kind === 'progress' && drop.key && !forced) return await progress($, drop, away, now)
    const route = forced ?? routeFor(drop.kind, drop.force, away)
    if (route === 'hold') return held(now)
    const r = await post($, drop, route === 'silent')
    if (r.ok) {
      st.lastSentAt = now
      await persist($)
    }
    return r.message
  } catch (err) {
    return `discord-drop: the card failed (${String(err).replace(URL_RE, '<url>').slice(0, 200)}).`
  }
}

// ── the person ──

/** A message from the user: they're here now, in this session and for jobs reading presence.json. */
async function heard($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  st.lastUserAt = now
  st.safetyFired = false
  disarm()
  await persist($)
  if (!env.dir) return
  try {
    const file = `${env.dir}/presence.json`
    await $.fs.write(file, `${JSON.stringify(presenceWith(await readJson($, file), env.sessionId, now, env.host))}\n`)
  } catch {
    // jobs then read an older presence and send rather than hold
  }
}

/** True when the user wrote to any session within the away time. */
async function anyoneHere($: EngineInterface, now: number): Promise<boolean> {
  const shared = env.dir ? latestUserAt(await readJson($, `${env.dir}/presence.json`)) : null
  const latest = Math.max(st.lastUserAt ?? 0, shared ?? 0)
  return !isAway(latest || null, now, cfg.awayMinutes)
}

/** In `needsYouMinutes`, the question or the permission prompt goes to Discord, unless answered first. */
function arm($: EngineInterface, tool: string, title: string, text: string): void {
  disarm()
  const armedAt = st.lastUserAt
  const timer = $.clock.after(cfg.needsYouMinutes * 60_000, () => {
    if (waiting?.timer !== timer) return
    waiting = null
    if (st.lastUserAt !== armedAt) return
    void send($, own({ kind: 'needs-you', title, text }), 'ping')
  })
  waiting = { timer, tool }
}

function disarm(tool?: string): void {
  if (!waiting || (tool !== undefined && waiting.tool !== tool)) return
  waiting.timer.cancel()
  waiting = null
}

// ── jobs, the allocation, scratch ──

async function renderChart($: EngineInterface, job: PaceJob): Promise<string | null> {
  const svg = lossChart(job)
  if (!svg || !env.dir) return null
  return toPng($, svg, `${env.dir}/out/${job.jobId}-loss`)
}

/** The SVG at `${base}.svg`, drawn to `${base}.png` at twice its size. */
async function toPng($: EngineInterface, svg: string, base: string): Promise<string | null> {
  try {
    await $.fs.write(`${base}.svg`, svg)
    const r = await $.process.run(['rsvg-convert', '-z', '2', '-o', `${base}.png`, `${base}.svg`], { timeoutMs: 20_000 })
    return r.exitCode === 0 && (await exists($, `${base}.png`)) ? `${base}.png` : null
  } catch {
    return null
  }
}

/** pace-line's jobs and alerts in this session, or undefined (not installed, not on a cluster). */
async function paceJobs($: EngineInterface): Promise<PaceJobs | undefined> {
  try {
    return ((await $.state.get({ plugin: 'pace-line', key: 'jobs' } as never)) as { value?: unknown } | undefined)?.value as PaceJobs | undefined
  } catch {
    return undefined
  }
}

/** pace-line's new alerts, as cards, when nobody is at a terminal. */
async function bridge($: EngineInterface): Promise<void> {
  const jobs = await paceJobs($)
  const fresh = (jobs?.alerts ?? []).filter(a => a.at > st.bridgeAfter).sort((a, b) => a.at - b.at)
  if (!jobs || !fresh.length) return
  st.bridgeAfter = fresh[fresh.length - 1]!.at
  await persist($)
  const now = await $.clock.now()
  // here: pace-line's toasts and Claude's own reply tell them
  if (await anyoneHere($, now)) return
  for (const a of fresh) {
    const job = jobs.jobs.find(j => j.id === a.job)
    // the job reported itself through jobkit.notify()
    if (a.kind === 'ended' && job?.workDir && (await exists($, `${job.workDir}/runs/${job.jobId}/notified.json`))) continue
    const image = a.kind === 'ended' && job ? await renderChart($, job) : null
    const r = await post($, alertDrop(a, job, cfg.lang, image), false)
    if (r.ok) st.lastSentAt = now
  }
  await persist($)
}

/** Before the allocation ends: Claude hands off, or the mod does. */
async function watchEnd($: EngineInterface): Promise<void> {
  if (env.endsAt === null || st.handoff === 'done' || !cfg.sessionEndMinutes) return
  const now = await $.clock.now()
  const left = env.endsAt - now
  if (left <= 0) return
  const window = cfg.sessionEndMinutes * 60_000
  if (st.handoff === 'none' && left <= window) {
    // here: pace-line's countdown already warns them
    if (!isAway(st.lastUserAt, now, cfg.awayMinutes)) {
      st.handoff = 'done'
      await persist($)
      return
    }
    st.handoff = 'asked'
    st.handoffAskedAt = now
    await persist($)
    try {
      await $.prompt.submit({ text: handoffPrompt(fmtDur(left / 1000), env.ownJob) })
    } catch {
      // no session to ask: the fallback below sends it
    }
    return
  }
  if (st.handoff === 'asked' && left <= window / 2) {
    st.handoff = 'done'
    await persist($)
    if (st.lastSentAt >= st.handoffAskedAt) return
    await send($, own({ kind: 'urgent', title: S().sessionEnds(fmtDur(left / 1000)), text: `${S().sessionEndsText}\n\n${cut(lastAssistant || '—', 1500)}` }), 'ping')
  }
}

/** Days before the monthly /scratch purge: what lives there, once per purge. */
async function checkPurge($: EngineInterface): Promise<void> {
  if (!cfg.purgeWarnDays || !env.user) return
  const now = await $.clock.now()
  const p = nextPurge(now, env.tzMinutes)
  if (p.daysLeft > cfg.purgeWarnDays) return
  const id = `purge:${p.year}-${p.month}-${p.day}`
  const scratch = `/scratch/${env.user}`
  if ((await $.store.get(id)) || !(await exists($, scratch))) return
  await $.store.set(id, now)
  let rows: [number, string][] = []
  try {
    const du = await $.process.run(['sh', '-c', 'du -s -B1G -- "$1"/* 2>/dev/null | sort -rn | head -n 12', 'sh', scratch], { timeoutMs: 300_000 })
    rows = du.stdout.split('\n').map(l => /^(\d+)\s+(.+)$/.exec(l.trim())).filter((m): m is RegExpExecArray => !!m).map(m => [Number(m[1]), m[2]!])
  } catch {
    // the card goes without sizes
  }
  const total = rows.reduce((t, r) => t + r[0], 0)
  const date = cfg.lang === 'es' ? `${p.day} ${MONTHS.es[p.month - 1]}` : `${MONTHS.en[p.month - 1]} ${p.day}`
  if (await anyoneHere($, now)) {
    $.ui.toast(`discord-drop: ${S().purgeTitle(date)}${total ? ` · ${total} GB in ${scratch}` : ''}`, { timeoutMs: 30_000 })
    return
  }
  const fields: Field[] = rows.map(([gb, path]) => ({ name: path.split('/').pop() || path, value: `${gb} GB`, inline: true }))
  await send($, own({ kind: 'urgent', title: S().purgeTitle(date), text: `${S().purgeText}\n-# \`${scratch}\`${total ? ` · ${total} GB` : ''}`, fields }), 'ping')
}

// ── /drop ──

async function status($: EngineInterface): Promise<string> {
  const now = await $.clock.now()
  const url = env.url ? 'set (DISCORD_WEBHOOK_URL)' : (await webhook($)) ? `set (${env.dir}/webhook)` : 'missing: set DISCORD_WEBHOOK_URL'
  const you = st.lastUserAt === null
    ? 'no message from you yet in this session (counts as away)'
    : `${isAway(st.lastUserAt, now, cfg.awayMinutes) ? 'away' : 'here'}: your last message was ${fmtDur((now - st.lastUserAt) / 1000)} ago`
  const p = nextPurge(now, env.tzMinutes)
  const jobs = await paceJobs($)
  return [
    'discord-drop',
    `· webhook: ${url}`,
    `· you: ${you}`,
    `· cards reach Discord after ${cfg.awayMinutes} min away; a question or permission prompt after ${cfg.needsYouMinutes} min`,
    env.endsAt !== null ? `· this allocation ends in ${fmtDur((env.endsAt - now) / 1000)}; hand-off ${cfg.sessionEndMinutes} min before` : '· not inside a Slurm allocation',
    jobs ? `· pace-line: ${jobs.jobs.length} batch job${jobs.jobs.length === 1 ? '' : 's'} watched; their alerts become cards while you're away` : '· pace-line: not watching jobs in this session (no alerts to forward)',
    cfg.purgeWarnDays ? `· next /scratch purge: ${p.year}-${String(p.month).padStart(2, '0')}-${String(p.day).padStart(2, '0')} (in ${p.daysLeft} d)` : '· purge warning off',
    '/drop test sends a sample card.',
  ].join('\n')
}

/** A sample card with a made-up loss chart, sent whoever is here. */
async function test($: EngineInterface): Promise<string> {
  const xs = Array.from({ length: 300 }, (_, i) => i * 20)
  const ys = xs.map((s, i) => 2.2 * Math.exp(-s / 1800) + 0.3 + 0.08 * Math.sin(i * 1.7))
  const svg = chartSvg({ title: 'demo-run (0000)', xName: 'step', series: [
    { label: 'loss', xs, ys, color: PALETTE[0]!, isFaint: true },
    { label: 'loss (EMA)', xs, ys: ema(ys), color: PALETTE[0]! },
  ] })
  const image = svg && env.dir ? await toPng($, svg, `${env.dir}/out/test`) : null
  const fields: Field[] = [
    { name: 'mAP', value: '43.0', inline: true }, { name: 'baseline', value: '41.2', inline: true }, { name: 'Δ', value: '+1.8', inline: true },
  ]
  const r = await post($, own({ kind: 'result', title: S().test, text: `${S().testText}\n\`\`\`diff\n+ mAP 43.0 (+1.8)\n- latency 41 ms (+3 ms)\n\`\`\``, fields, image, force: true }), false)
  return r.ok ? 'Sent a sample card to Discord.' : r.message
}

// ── start-up ──

async function start($: EngineInterface, cwd: string): Promise<void> {
  const home = (await $.env.get('HOME')) ?? ''
  env.user = (await $.env.get('USER')) ?? (await $.env.get('LOGNAME')) ?? ''
  env.host = (await $.env.get('SLURMD_NODENAME')) ?? (await $.env.get('HOSTNAME')) ?? 'host'
  env.url = (await $.env.get('DISCORD_WEBHOOK_URL'))?.trim() || null
  env.ownJob = (await $.env.get('SLURM_JOB_ID')) ?? null
  const end = Number(await $.env.get('SLURM_JOB_END_TIME'))
  env.endsAt = Number.isFinite(end) && end > 0 ? end * 1000 : null
  env.sessionId = await $.session.id()
  env.project = cwd.split('/').filter(Boolean).pop() ?? null
  env.dir = home ? `${home}/.claude/discord-drop` : ''
  try {
    const z = (await $.process.run(['date', '+%z'], { timeoutMs: 5_000 })).stdout.trim()
    const m = /^([+-])(\d\d)(\d\d)$/.exec(z)
    if (m) env.tzMinutes = (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3]))
  } catch {
    // UTC dates then
  }

  const saved = (await $.store.get(sessionKey())) as Raw | undefined
  const now = await $.clock.now()
  if (saved) {
    st.lastUserAt = typeof saved.lastUserAt === 'number' ? saved.lastUserAt : null
    st.lastSentAt = typeof saved.lastSentAt === 'number' ? saved.lastSentAt : 0
    st.safetyFired = saved.safetyFired === true
    st.handoff = saved.handoff === 'asked' || saved.handoff === 'done' ? saved.handoff : 'none'
    st.handoffAskedAt = typeof saved.handoffAskedAt === 'number' ? saved.handoffAskedAt : 0
  }
  // alerts raised before this load were pace-line's to tell, not ours to repeat
  st.bridgeAfter = typeof saved?.bridgeAfter === 'number' ? saved.bridgeAfter : now
  await persist($)
  const old = (await $.store.keys()).filter(k => k.startsWith('s:') && k !== sessionKey())
  for (const k of old.slice(0, Math.max(0, old.length - (KEEP_SESSIONS - 1)))) await $.store.delete(k)

  if (!env.dir) return
  try {
    // jobs on other nodes read the same threshold, and the webhook from the file
    await $.fs.write(`${env.dir}/config.json`, `${JSON.stringify({ awayMinutes: cfg.awayMinutes, language: cfg.lang })}\n`)
    if (env.url && (await readText($, `${env.dir}/webhook`))?.trim() !== env.url) {
      await $.process.run(['sh', '-c', 'umask 077 && mkdir -p "$1" && cat > "$1/webhook" && chmod 600 "$1/webhook"', 'sh', env.dir], { stdin: `${env.url}\n`, timeoutMs: 5_000 })
    }
    await $.process.run(['find', `${env.dir}/out`, '-type', 'f', '-mtime', '+7', '-delete'], { timeoutMs: 10_000 })
  } catch {
    // a card still goes from this session
  }
}

export const register: Register = (on, options) => {
  const n = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? v : d)
  cfg.awayMinutes = n(options.awayMinutes, 30)
  cfg.needsYouMinutes = n(options.needsYouMinutes, 5)
  cfg.safetyNet = options.safetyNet !== false
  cfg.sessionEndMinutes = n(options.sessionEndMinutes, 30)
  cfg.purgeWarnDays = n(options.purgeWarnDays, 3)
  cfg.lang = options.language === 'en' ? 'en' : 'es'

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await start($, e.cwd)
    $.clock.every(15_000, () => void bridge($).catch(() => undefined))
    $.clock.every(60_000, () => void watchEnd($).catch(() => undefined))
    $.clock.every(6 * 3600_000, () => void checkPurge($).catch(() => undefined))
    void checkPurge($).catch(() => undefined)
    await $.command.register({ name: 'drop', description: 'Discord cards: where things stand, or a sample card', argumentHint: 'status | test' })
    return started
  })

  // the rules ride the first prompt of a session (and of a reload, and after a compaction):
  // the system-prompt route does not reach the model on every host
  on('prompt.submit', async ($, e, next) => {
    const kind = e.origin.kind
    turnOrigin = kind
    if (kind === 'composer' || kind === 'bridge') await heard($)
    if (hasToldRules || (kind !== 'composer' && kind !== 'bridge' && kind !== 'sdk')) return next(e)
    hasToldRules = true
    return next({ ...e, context: [...(e.context ?? []), rules(cfg.awayMinutes)] })
  }).catch(($, e, next) => next(e))

  on('session.compact', async ($, e, next) => {
    hasToldRules = false
    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    const input = e as unknown as Raw
    if (e.tool === 'Bash' && typeof input.command === 'string' && OP_LINE.test(input.command)) {
      const raw = opFrom(input.command)
      if (typeof raw === 'string') return { deny: raw }
      const drop = dropFrom(raw)
      if (typeof drop === 'string') return { deny: drop }
      return shell(await send($, drop))
    }
    if (!e.agentId && (e.tool === 'AskUserQuestion' || e.tool === 'ExitPlanMode')) {
      const isPlan = e.tool === 'ExitPlanMode'
      arm($, e.tool, isPlan ? S().planReady : S().needsAnswer, isPlan ? S().answerInTerminal : questionsText(input, S()))
      try {
        return await next(e)
      } finally {
        disarm(e.tool)
      }
    }
    try {
      return await next(e)
    } finally {
      // a permission prompt for this call was answered
      disarm(e.tool)
    }
  }).catch(($, e, next) => next(e))

  // a permission dialog really shown (no hook settled it): the clock starts
  on('classic.PermissionRequest', async ($, e, next) => {
    const answer = await next(e)
    if (answer.decision) return answer
    arm($, e.tool_name, S().needsPermission, describe(e.tool_name, e.tool_input))
    return answer
  }).catch(($, e, next) => next(e))

  on('classic.PermissionDenied', async ($, e, next) => {
    disarm()
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) disarm()
    return next(e)
  })

  // the safety net: a long stretch of work ended while they're away, and nothing told them
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    if (e.agent_id) return result
    if (e.last_assistant_message) lastAssistant = e.last_assistant_message
    if (!cfg.safetyNet || e.stop_hook_active || result.block || (e.background_tasks?.length ?? 0) > 0 || !NET_ORIGINS.has(turnOrigin)) return result
    const since = st.lastUserAt
    if (since === null || st.safetyFired || st.lastSentAt >= since) return result
    const now = await $.clock.now()
    if (!isAway(since, now, cfg.awayMinutes)) return result
    st.safetyFired = true
    await persist($)
    const msg = (e.last_assistant_message ?? '').trim()
    const asks = /\?\s*$/.test(msg)
    await send($, own({ kind: asks ? 'needs-you' : 'done', title: asks ? S().question : S().finished, text: cut(msg, 1800), fields: [tookField(S(), (now - since) / 1000)] }))
    return result
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'drop' }, async ($, e) => {
    const sub = e.args.trim().split(/\s+/)[0] || 'status'
    return { text: sub === 'test' ? await test($) : await status($) }
  })
}

files.hooks/bridge.ts:
// pace-line's batch-job alerts as cards. pace-line watches Slurm and keeps its
// alerts in its session state; this turns one alert and its job into a Drop,
// and the job's metrics into a loss chart. Pure.

import { chartSvg, ema, fmt, PALETTE } from './chart'
import { cut, fmtDur } from './drop'
import type { Drop, Field, Kind } from './drop'
import type { Lang } from './embed'

/** The part of pace-line's state read here (pace-line's types/index.d.ts has the whole). */
export type PaceSeries = { step: number[]; value: number[] }
export type PaceMetrics = { keys: Record<string, PaceSeries>; lastStep: number | null; totalSteps: number | null; epoch: number | null; totalEpochs: number | null }
export type PaceJob = {
  id: string
  jobId: string
  name: string
  state: string
  elapsedS: number | null
  nodes: number
  gpus: number | null
  gpuType: string | null
  submittedAt: number | null
  startedAt: number | null
  workDir: string | null
  stdout: string | null
  exitCode: string | null
  lastLines: string[]
  metrics: PaceMetrics | null
  ckpt: { name: string; path: string } | null
}
export type PaceAlert = { job: string; kind: string; level: 'info' | 'warn' | 'error'; text: string; at: number }
export type PaceJobs = { jobs: PaceJob[]; alerts: PaceAlert[] }

const LABEL: Record<Lang, Record<string, string>> = {
  es: {
    completed: 'terminó', ended: 'falló', oom: 'sin memoria (OOM)', nccl: 'error de NCCL', traceback: 'lanzó una excepción',
    nonFinite: 'métrica NaN/inf', silent: 'log en silencio', idle: 'GPU ociosa', nearLimit: 'cerca del límite de tiempo',
    staleCkpt: 'sin checkpoint nuevo', pending: 'lleva mucho en cola', started: 'arrancó', resumed: 'reenviado desde checkpoint',
    resumeStopped: 'auto-resume parado',
  },
  en: {
    completed: 'completed', ended: 'failed', oom: 'out of memory', nccl: 'NCCL error', traceback: 'raised an exception',
    nonFinite: 'metric went NaN/inf', silent: 'log silent', idle: 'GPU idle', nearLimit: 'near its time limit',
    staleCkpt: 'no new checkpoint', pending: 'pending a long time', started: 'started', resumed: 'resubmitted from checkpoint',
    resumeStopped: 'auto-resume stopped',
  },
}
const FIELD: Record<Lang, Record<string, string>> = {
  es: { took: 'Duración', gpus: 'GPUs', steps: 'Pasos', epoch: 'Época', ckpt: 'Checkpoint', exit: 'Salida', log: 'Log', queued: 'En cola', loss: 'loss' },
  en: { took: 'Took', gpus: 'GPUs', steps: 'Steps', epoch: 'Epoch', ckpt: 'Checkpoint', exit: 'Exit', log: 'Log', queued: 'Queued', loss: 'loss' },
}

/** Whether a metric improves downwards: losses and errors do. */
export function lowerIsBetter(key: string): boolean {
  return /loss|err|wer|cer|mae|mse|rmse|perplexity|ppl/i.test(key)
}

export function lossKey(m: PaceMetrics): string | null {
  const keys = Object.keys(m.keys)
  return keys.find(k => k === 'loss') ?? keys.find(k => k === 'train_loss') ?? keys.find(k => /loss$/.test(k) && !/^val/.test(k)) ?? null
}
export const valKeys = (m: PaceMetrics) => Object.keys(m.keys).filter(k => /^val[_/]/.test(k))

const finite = (s: PaceSeries) => s.value.filter(Number.isFinite)
const last = (s: PaceSeries) => finite(s).pop() ?? null
const best = (key: string, s: PaceSeries) => {
  const v = finite(s)
  return v.length ? (lowerIsBetter(key) ? Math.min(...v) : Math.max(...v)) : null
}

/** What a card of this alert is. */
export function kindOf(a: PaceAlert, job: PaceJob | undefined): Kind {
  if (a.kind === 'ended') return job?.state === 'COMPLETED' || a.level === 'info' ? 'result' : 'urgent'
  if (a.kind === 'started') return 'started'
  if (a.kind === 'pending' || a.kind === 'resumed') return 'done'
  return 'urgent'
}

/** The card for one alert; `image` is the loss chart's PNG when there is one. */
export function alertDrop(a: PaceAlert, job: PaceJob | undefined, lang: Lang, image: string | null): Drop {
  const kind = kindOf(a, job)
  const L = LABEL[lang]
  const F = FIELD[lang]
  const name = job?.name ?? `job ${a.job}`
  const label = a.kind === 'ended' ? (kind === 'result' ? L.completed : `${L.ended}: ${job?.state ?? ''}`.replace(/: $/, '')) : (L[a.kind] ?? a.kind)
  const fields: Field[] = []
  if (job?.elapsedS !== null && job?.elapsedS !== undefined) fields.push({ name: F.took, value: fmtDur(job.elapsedS), inline: true })
  if (job?.gpus) fields.push({ name: F.gpus, value: `${job.gpus}×${job.gpuType ?? 'GPU'}${job.nodes > 1 ? ` · ${job.nodes} nodes` : ''}`, inline: true })
  if (a.kind === 'started' && job?.submittedAt && job.startedAt) fields.push({ name: F.queued, value: fmtDur((job.startedAt - job.submittedAt) / 1000), inline: true })
  const m = job?.metrics
  if (m && (kind === 'result' || kind === 'urgent')) {
    if (m.lastStep !== null) fields.push({ name: F.steps, value: m.totalSteps ? `${m.lastStep}/${m.totalSteps}` : String(m.lastStep), inline: true })
    if (m.epoch !== null) fields.push({ name: F.epoch, value: m.totalEpochs ? `${m.epoch}/${m.totalEpochs}` : String(m.epoch), inline: true })
    const lk = lossKey(m)
    const lv = lk ? ema(finite(m.keys[lk]!)).pop() : undefined
    if (lk && lv !== undefined) fields.push({ name: lk, value: fmt(lv), inline: true })
    for (const k of valKeys(m).slice(0, 6)) {
      const v = last(m.keys[k]!)
      const b = best(k, m.keys[k]!)
      if (v !== null) fields.push({ name: k, value: b !== null && b !== v ? `${fmt(v)} · best ${fmt(b)}` : fmt(v), inline: true })
    }
  }
  if (job?.ckpt && kind === 'result') fields.push({ name: F.ckpt, value: `\`${cut(job.ckpt.name, 100)}\``, inline: false })
  if (kind === 'urgent' && job?.exitCode && job.exitCode !== '0:0') fields.push({ name: F.exit, value: job.exitCode, inline: true })
  if (kind === 'urgent' && job?.stdout) fields.push({ name: F.log, value: `\`${cut(job.stdout, 200)}\``, inline: false })
  const tail = kind === 'urgent' && job?.lastLines.length ? `\n\`\`\`\n${cut(job.lastLines.slice(-10).join('\n'), 1400)}\n\`\`\`` : ''
  return {
    kind,
    title: `${name} ${label}`,
    text: `-# ${cut(a.text, 300)}${tail}`,
    fields,
    image,
    files: [],
    url: null,
    key: null,
    progress: null,
    eta: null,
    final: false,
    force: false,
    author: job ? `${job.name} (${job.id})` : `job ${a.job}`,
    footer: `job ${a.job}`,
  }
}

/** The job's loss chart (train loss, its EMA, val loss with its best ringed), or null. */
export function lossChart(job: PaceJob): string | null {
  const m = job.metrics
  if (!m) return null
  const lk = lossKey(m)
  const vk = valKeys(m).find(k => /loss/.test(k)) ?? (lk ? null : valKeys(m)[0] ?? null)
  if (!lk && !vk) return null
  const series = []
  if (lk) {
    const s = m.keys[lk]!
    series.push({ label: lk, xs: s.step, ys: s.value, color: PALETTE[0]!, isFaint: true })
    series.push({ label: `${lk} (EMA)`, xs: s.step, ys: ema(s.value), color: PALETTE[0]! })
  }
  let marker
  if (vk) {
    const s = m.keys[vk]!
    series.push({ label: vk, xs: s.step, ys: s.value, color: PALETTE[1]! })
    const b = best(vk, s)
    const i = b === null ? -1 : s.value.indexOf(b)
    if (i >= 0) marker = { x: s.step[i]!, y: b!, color: PALETTE[1]!, label: `best ${fmt(b!)}` }
  }
  return chartSvg({ title: `${job.name} (${job.id})`, xName: 'step', series, marker })
}

files.hooks/chart.ts:
// A still line chart for a card: flat colours on Discord's dark card
// background, nice ticks, a legend, the last value labelled and the best
// point ringed. No CSS variables or media queries: librsvg 2.50 turns it
// into the PNG Discord shows. Pure: series in, an `<svg>` string out.

const BG = '#2b2d31'
const INK = '#f2f3f5'
const MUTED = '#949ba4'
const GRID = '#3f4147'
const AXIS = '#4e5058'
export const PALETTE = ['#3987e5', '#e8742f', '#23a55a', '#d4a72c', '#d55181', '#9085e9']
const FONT = 'DejaVu Sans, Liberation Sans, sans-serif'

export type ChartSeries = {
  label: string
  xs: readonly number[]
  ys: readonly number[]
  color: string
  /** A faint thin line under the others (raw loss under its EMA). */
  isFaint?: boolean
}

export type ChartSpec = {
  title?: string
  series: readonly ChartSeries[]
  width?: number
  height?: number
  xName?: string
  /** A point to ring and label, e.g. the best validation value. */
  marker?: { x: number; y: number; color: string; label: string }
  /** Log y when every value is positive and they span over two decades. */
  allowLog?: boolean
}

const r1 = (v: number) => Math.round(v * 10) / 10
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const trim = (v: number, d: number) => v.toFixed(d).replace(/\.?0+$/, '')

/** 0.000412 → "4.1e-4", 12345 → "12.3k", 0.4123 → "0.412". */
export function fmt(v: number): string {
  if (!Number.isFinite(v)) return String(v)
  const a = Math.abs(v)
  if (a === 0) return '0'
  if (a >= 1e6) return `${trim(v / 1e6, 1)}M`
  if (a >= 1e4) return `${trim(v / 1e3, a >= 1e5 ? 0 : 1)}k`
  if (a >= 1000) return `${trim(v / 1e3, 2)}k`
  if (a >= 100) return v.toFixed(0)
  if (a >= 10) return trim(v, 1)
  if (a >= 0.01) return trim(v, 3)
  return v.toExponential(1)
}

/** Ticks at 1, 2, 2.5 or 5 × 10^k covering [min, max], about `count` of them. */
export function niceTicks(min: number, max: number, count = 4): number[] {
  if (!(max > min)) return [min]
  const raw = (max - min) / Math.max(1, count)
  const mag = 10 ** Math.floor(Math.log10(raw))
  const step = [1, 2, 2.5, 5, 10].map(m => m * mag).find(s => s >= raw * 0.75) ?? 10 * mag
  const out: number[] = []
  for (let v = Math.floor(min / step) * step; v <= max + step * 1e-9; v += step) out.push(Math.round(v / step) * step)
  if (out[out.length - 1]! < max - step * 1e-9) out.push(out[out.length - 1]! + step)
  return out
}

/** At most about 2 × `buckets` points, keeping each bucket's first, lowest, highest and last. */
export function decimate(xs: readonly number[], ys: readonly number[], buckets: number): { xs: number[]; ys: number[] } {
  const pts: [number, number][] = []
  for (let i = 0; i < xs.length; i++) if (Number.isFinite(xs[i]) && Number.isFinite(ys[i])) pts.push([xs[i]!, ys[i]!])
  if (pts.length <= buckets * 2) return { xs: pts.map(p => p[0]), ys: pts.map(p => p[1]) }
  const x0 = pts[0]![0]
  const span = pts[pts.length - 1]![0] - x0 || 1
  const keep = new Set<number>()
  let b = -1, first = 0, lo = 0, hi = 0
  const flush = (last: number) => { if (b >= 0) for (const i of [first, lo, hi, last]) keep.add(i) }
  for (let i = 0; i < pts.length; i++) {
    const k = Math.min(buckets - 1, Math.floor(((pts[i]![0] - x0) / span) * buckets))
    if (k !== b) {
      flush(i - 1)
      b = k; first = i; lo = i; hi = i
    } else {
      if (pts[i]![1] < pts[lo]![1]) lo = i
      if (pts[i]![1] > pts[hi]![1]) hi = i
    }
  }
  flush(pts.length - 1)
  const idx = [...keep].sort((a, c) => a - c)
  return { xs: idx.map(i => pts[i]![0]), ys: idx.map(i => pts[i]![1]) }
}

/** Exponential moving average, the smoothing TensorBoard's slider applies. */
export function ema(values: readonly number[], alpha = 0.9): number[] {
  const out: number[] = []
  let acc: number | null = null
  for (const v of values) {
    acc = acc === null || !Number.isFinite(acc) ? v : alpha * acc + (1 - alpha) * v
    out.push(acc)
  }
  return out
}

/** The chart, or null when there is nothing to draw. */
export function chartSvg(spec: ChartSpec): string | null {
  const W = spec.width ?? 800
  const H = spec.height ?? 360
  const series = spec.series.filter(s => s.xs.some((x, i) => Number.isFinite(x) && Number.isFinite(s.ys[i])))
  if (!series.length) return null

  let xMin = Infinity, xMax = -Infinity, yMin = Infinity, yMax = -Infinity
  for (const s of series) {
    for (let i = 0; i < s.xs.length; i++) {
      const x = s.xs[i]!, y = s.ys[i]!
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue
      xMin = Math.min(xMin, x); xMax = Math.max(xMax, x)
      yMin = Math.min(yMin, y); yMax = Math.max(yMax, y)
    }
  }
  if (xMax === xMin) { xMin -= 1; xMax += 1 }
  const isLog = !!spec.allowLog && yMin > 0 && yMax / yMin > 100
  let ticks: number[]
  if (isLog) {
    ticks = []
    for (let v = 10 ** Math.floor(Math.log10(yMin)); v <= 10 ** Math.ceil(Math.log10(yMax)) * 1.0001; v *= 10) ticks.push(v)
  } else {
    if (yMax === yMin) { const pad = Math.abs(yMax) * 0.05 || 1; yMin -= pad; yMax += pad }
    ticks = niceTicks(yMin, yMax, 5)
  }
  const lo = ticks[0]!
  const hi = ticks[ticks.length - 1]!

  const labelled = series.filter(s => !s.isFaint)
  const titleH = spec.title ? 30 : 8
  const legendH = labelled.length >= 2 ? 22 : 0
  const top = titleH + legendH + 8
  const left = Math.max(...ticks.map(t => fmt(t).length)) * 8 + 18
  const right = 70
  const bottom = 34
  const pw = W - left - right
  const ph = H - top - bottom
  const sx = (x: number) => left + ((x - xMin) / (xMax - xMin)) * pw
  const ty = (y: number) => (isLog ? Math.log10(y) : y)
  const sy = (y: number) => top + ph - ((ty(Math.min(hi, Math.max(lo, y))) - ty(lo)) / (ty(hi) - ty(lo))) * ph

  const parts: string[] = [`<rect width="${W}" height="${H}" rx="8" fill="${BG}"/>`]
  if (spec.title) parts.push(`<text x="${left}" y="22" fill="${INK}" font-size="15" font-weight="600">${esc(spec.title)}</text>`)
  for (const t of ticks) {
    const y = r1(sy(t))
    parts.push(`<line x1="${left}" x2="${r1(left + pw)}" y1="${y}" y2="${y}" stroke="${GRID}" stroke-width="1"/>`)
    parts.push(`<text x="${r1(left - 8)}" y="${r1(y + 4)}" fill="${MUTED}" font-size="12" text-anchor="end">${fmt(t)}</text>`)
  }
  parts.push(`<line x1="${left}" x2="${r1(left + pw)}" y1="${r1(top + ph)}" y2="${r1(top + ph)}" stroke="${AXIS}" stroke-width="1"/>`)
  for (const t of niceTicks(xMin, xMax, Math.max(2, Math.floor(pw / 120)))) {
    if (t < xMin || t > xMax) continue
    parts.push(`<text x="${r1(sx(t))}" y="${r1(top + ph + 18)}" fill="${MUTED}" font-size="12" text-anchor="middle">${esc(fmt(t))}</text>`)
  }
  if (spec.xName) parts.push(`<text x="${r1(left + pw)}" y="${H - 4}" fill="${MUTED}" font-size="11" text-anchor="end">${esc(spec.xName)}</text>`)

  for (const s of [...series.filter(x => x.isFaint), ...labelled]) {
    const d = decimate(s.xs, s.ys, Math.round(pw))
    if (!d.xs.length) continue
    const path = d.xs.map((x, i) => `${i ? 'L' : 'M'}${r1(sx(x))} ${r1(sy(d.ys[i]!))}`).join('')
    parts.push(s.isFaint
      ? `<path d="${path}" fill="none" stroke="${s.color}" stroke-opacity="0.35" stroke-width="1.2" stroke-linejoin="round"/>`
      : `<path d="${path}" fill="none" stroke="${s.color}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`)
    if (s.isFaint) continue
    // The last value beside the line's end.
    const i = d.xs.length - 1
    const x = sx(d.xs[i]!), y = sy(d.ys[i]!)
    // past a marker ring sitting on this very point
    const isRinged = spec.marker !== undefined && Math.abs(sx(spec.marker.x) - x) < 6 && Math.abs(sy(spec.marker.y) - y) < 6
    parts.push(`<circle cx="${r1(x)}" cy="${r1(y)}" r="4" fill="${s.color}" stroke="${BG}" stroke-width="2"/>`)
    parts.push(`<text x="${r1(x + (isRinged ? 14 : 8))}" y="${r1(Math.min(top + ph, Math.max(top + 10, y + 4)))}" fill="${s.color}" font-size="12" font-weight="600">${esc(fmt(d.ys[i]!))}</text>`)
  }

  if (spec.marker && Number.isFinite(spec.marker.x) && Number.isFinite(spec.marker.y)) {
    const x = sx(spec.marker.x), y = sy(spec.marker.y)
    const c = spec.marker.color
    parts.push(`<circle cx="${r1(x)}" cy="${r1(y)}" r="9" fill="none" stroke="${c}" stroke-width="1.6"/>`)
    const above = y - top > 26
    const anchor = x > left + pw * 0.75 ? 'end' : x < left + pw * 0.25 ? 'start' : 'middle'
    parts.push(`<text x="${r1(x)}" y="${r1(above ? y - 15 : y + 26)}" fill="${INK}" font-size="12" text-anchor="${anchor}">${esc(spec.marker.label)}</text>`)
  }

  if (legendH) {
    let x = left
    const y = titleH + 12
    for (const s of labelled) {
      parts.push(`<line x1="${x}" x2="${x + 16}" y1="${y}" y2="${y}" stroke="${s.color}" stroke-width="3" stroke-linecap="round"/>`)
      parts.push(`<text x="${x + 22}" y="${y + 4}" fill="${INK}" font-size="12">${esc(s.label)}</text>`)
      x += 22 + s.label.length * 7.5 + 22
    }
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" font-family="${FONT}">${parts.join('')}</svg>`
}

files.hooks/drop.ts:
// What a drop is and when it goes out. Pure: the op Claude writes in, a
// validated Drop out; the delivery rule; presence; the purge calendar.

export type Kind = 'done' | 'result' | 'urgent' | 'needs-you' | 'progress' | 'started'
export const KINDS: readonly Kind[] = ['done', 'result', 'urgent', 'needs-you', 'progress', 'started']

export type Field = { name: string; value: string; inline: boolean }

export type Drop = {
  kind: Kind
  title: string
  text: string
  fields: Field[]
  /** Absolute path of the picture shown inside the card. */
  image: string | null
  /** Absolute paths attached under the card. */
  files: string[]
  url: string | null
  /** A progress card's name: the same key edits the same card. */
  key: string | null
  /** 0 to 1. */
  progress: number | null
  /** Unix seconds. */
  eta: number | null
  final: boolean
  /** The user asked for it: it goes out whether they're here or not. */
  force: boolean
  author: string | null
  footer: string | null
}

/** ping: a message that notifies; silent: one that doesn't; hold: nothing is sent. */
export type Route = 'ping' | 'silent' | 'hold'

export const MAX_FILES = 10
export const MAX_FILE_BYTES = 10 * 1024 * 1024

/** The shell no-op Claude sends a card with; the mod answers it, so nothing runs. */
export const OP_LINE = /^\s*:\s+drop\b/
export const TOOL = "a Bash call `: drop <<'EOF'` + one JSON op + `EOF`"

const EXAMPLE = `: drop <<'EOF'\n{"kind":"result","title":"Eval COCO val","text":"mAP 43.0 (+1.8)","image":"/abs/pr.png"}\nEOF`

type Raw = Record<string, unknown>

/** The op of a `: drop` call: the JSON in its heredoc, or a refusal. */
export function opFrom(command: string): Raw | string {
  const doc = /<<-?\s*(['"]?)(\w+)\1[^\n]*\n([\s\S]*?)\n\s*\2\s*$/.exec(command)
  const text = (doc ? (doc[3] ?? '') : command.replace(OP_LINE, '').replace(/^\s*'([\s\S]*)'\s*$/, '$1')).trim()
  try {
    const op = JSON.parse(text) as unknown
    if (op && typeof op === 'object' && !Array.isArray(op)) return op as Raw
  } catch {
    // falls through to the refusal
  }
  return `discord-drop: \`: drop\` needs one JSON op in a heredoc, e.g.\n${EXAMPLE}`
}

// the cut drops half a character left at the edge (an emoji is two UTF-16 units)
export const cut = (s: string, max: number) => (s.length <= max ? s : `${s.slice(0, max - 1).replace(/[\uD800-\uDBFF]$/, '')}…`)
const str = (v: unknown) => (typeof v === 'string' ? v.trim() : typeof v === 'number' && Number.isFinite(v) ? String(v) : '')
const num = (v: unknown) => (typeof v === 'number' && Number.isFinite(v) ? v : typeof v === 'string' && v.trim() !== '' && Number.isFinite(Number(v)) ? Number(v) : null)

/** Paths go to curl inside double quotes: none of the characters that would end them. */
const isSafePath = (p: string) => p.startsWith('/') && !/["\\\n\r;]/.test(p)

/** A Drop from Claude's op, or why not. */
export function dropFrom(raw: Raw): Drop | string {
  const kind = (KINDS as readonly string[]).includes(str(raw.kind)) ? (str(raw.kind) as Kind) : raw.key !== undefined && raw.progress !== undefined ? 'progress' : 'done'
  const title = str(raw.title)
  const text = str(raw.text)
  if (!title && !text) return `discord-drop: a drop needs a title or a text, e.g.\n${EXAMPLE}`
  const fields: Field[] = []
  if (raw.fields !== undefined && !Array.isArray(raw.fields)) return 'discord-drop: fields is a list of {"name","value","inline"}.'
  for (const f of (raw.fields as unknown[] | undefined) ?? []) {
    if (!f || typeof f !== 'object') continue
    const o = f as Raw
    const name = str(o.name)
    const value = str(o.value)
    if (!name && !value) continue
    fields.push({ name: name || '​', value: value || '​', inline: o.inline !== false })
  }
  const image = str(raw.image) || null
  const files = Array.isArray(raw.files) ? raw.files.map(str).filter(Boolean) : typeof raw.files === 'string' ? [str(raw.files)] : []
  for (const p of image ? [image, ...files] : files) {
    if (!isSafePath(p)) return `discord-drop: ${p} must be an absolute path without quotes, backslashes or semicolons.`
  }
  if (files.length + (image ? 1 : 0) > MAX_FILES) return `discord-drop: at most ${MAX_FILES} files per card (the image counts).`
  const url = str(raw.url)
  if (url && !/^https?:\/\/\S+$/.test(url)) return `discord-drop: url must be an http(s) link, got ${cut(url, 80)}.`
  const key = str(raw.key).toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || null
  let progress = num(raw.progress)
  if (progress !== null) progress = Math.max(0, Math.min(1, progress > 1 ? progress / 100 : progress))
  let eta = num(raw.eta)
  if (eta !== null && eta > 1e12) eta = Math.round(eta / 1000)
  if (kind === 'progress' && !key) return 'discord-drop: a progress card needs a key, so later updates edit it.'
  return {
    kind,
    title,
    text,
    fields,
    image,
    files,
    url: url || null,
    key,
    progress,
    eta,
    final: raw.final === true,
    force: raw.force === true,
    author: str(raw.author) || null,
    footer: str(raw.footer) || null,
  }
}

/** Away: no message from the user to this session for `awayMinutes`, or none yet. */
export function isAway(lastUserAt: number | null, now: number, awayMinutes: number): boolean {
  return lastUserAt === null || now - lastUserAt >= awayMinutes * 60_000
}

/** The delivery rule. Present: nothing goes unless asked. Away: everything pings, progress quietly. */
export function routeFor(kind: Kind, force: boolean, away: boolean): Route {
  if (force) return kind === 'progress' ? 'silent' : 'ping'
  if (!away) return 'hold'
  return kind === 'progress' ? 'silent' : 'ping'
}

/** ~/.claude/discord-drop/presence.json: every session's last message from the user, read by jobs on other nodes. */
export type Presence = { sessions: Record<string, { lastUserAt: number; host: string }> }

const WEEK = 7 * 24 * 3600_000

export function presenceWith(file: unknown, session: string, at: number, host: string): Presence {
  const prev = file && typeof file === 'object' && (file as Presence).sessions && typeof (file as Presence).sessions === 'object' ? (file as Presence).sessions : {}
  const sessions: Presence['sessions'] = {}
  for (const [id, s] of Object.entries(prev)) {
    if (s && typeof s.lastUserAt === 'number' && at - s.lastUserAt < WEEK) sessions[id] = { lastUserAt: s.lastUserAt, host: String(s.host ?? '') }
  }
  sessions[session] = { lastUserAt: at, host }
  return { sessions }
}

/** The newest message from the user in any session, or null. */
export function latestUserAt(file: unknown): number | null {
  const sessions = file && typeof file === 'object' ? (file as Presence).sessions : null
  if (!sessions || typeof sessions !== 'object') return null
  const times = Object.values(sessions).map(s => s?.lastUserAt).filter((t): t is number => typeof t === 'number')
  return times.length ? Math.max(...times) : null
}

/** "45 s", "12 min", "2 h 05 min", "3 d 4 h". */
export function fmtDur(seconds: number): string {
  const s = Math.max(0, Math.round(seconds))
  if (s < 60) return `${s} s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m} min`
  const h = Math.floor(m / 60)
  if (h < 48) return `${h} h ${String(m % 60).padStart(2, '0')} min`
  return `${Math.floor(h / 24)} d ${h % 24} h`
}

/**
 * The next monthly /scratch purge (the first Tuesday of the month), as a
 * local calendar date, on or after today's. `offsetMinutes` is the zone's
 * offset from UTC (-240 in Boston's summer).
 */
export function nextPurge(now: number, offsetMinutes: number): { year: number; month: number; day: number; daysLeft: number } {
  const local = new Date(now + offsetMinutes * 60_000)
  const y = local.getUTCFullYear()
  const m = local.getUTCMonth()
  const today = Date.UTC(y, m, local.getUTCDate())
  const firstTuesday = (year: number, month: number) => {
    const dow = new Date(Date.UTC(year, month, 1)).getUTCDay()
    return Date.UTC(year, month, 1 + ((2 - dow + 7) % 7))
  }
  let t = firstTuesday(y, m)
  if (t < today) t = firstTuesday(m === 11 ? y + 1 : y, (m + 1) % 12)
  const d = new Date(t)
  return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate(), daysLeft: Math.round((t - today) / 86_400_000) }
}

files.hooks/embed.ts:
// The card: a Discord embed with one colour and icon per kind, and the curl
// calls that post or edit it. Pure: a Drop in, the payload and argv out.
// The webhook URL never enters an argv: curl reads it from stdin (`-K -`).

import { cut, fmtDur } from './drop'
import type { Drop, Field, Kind } from './drop'

export const COLOR: Record<Kind, number> = {
  result: 0x2ecc71,
  urgent: 0xe74c3c,
  'needs-you': 0xf1c40f,
  progress: 0x3498db,
  started: 0x9b59b6,
  done: 0x5865f2,
}

export const ICON: Record<Kind, string> = {
  result: '✅',
  urgent: '🛑',
  'needs-you': '⏸️',
  progress: '⏳',
  started: '▶️',
  done: '✔️',
}

/** Discord's limits for one embed. */
const LIMIT = { title: 256, description: 4096, fields: 25, name: 256, value: 1024, footer: 2048, author: 256, total: 6000 }
/** SUPPRESS_NOTIFICATIONS: the message lands without a push or a sound. */
export const SILENT = 1 << 12

export type Lang = 'es' | 'en'
export const STRINGS = {
  es: {
    finished: 'He terminado',
    question: 'Tengo una pregunta',
    took: 'Duración',
    since: 'Desde tu último mensaje',
    needsPermission: 'Necesito tu permiso',
    needsAnswer: 'Necesito una respuesta',
    planReady: 'Plan listo para revisar',
    answerInTerminal: 'Responde en la terminal.',
    waiting: 'Esperando',
    sessionEnds: (m: string) => `Mi sesión se cierra en ${m}`,
    sessionEndsText: 'El dev-shell llega a su límite de tiempo. Lo último que hice:',
    purgeTitle: (d: string) => `Purga de /scratch el martes ${d}`,
    purgeText: 'La política de Research Computing borra /scratch el primer martes de cada mes. Mueve a /projects lo que no puedas volver a descargar.',
    test: 'Prueba de discord-drop',
    testText: 'Si ves esta tarjeta, el webhook funciona.',
    eta: 'ETA',
    full: 'Texto completo adjunto.',
  },
  en: {
    finished: 'Finished',
    question: 'I have a question',
    took: 'Took',
    since: 'Since your last message',
    needsPermission: 'I need your permission',
    needsAnswer: 'I need an answer',
    planReady: 'Plan ready for review',
    answerInTerminal: 'Answer in the terminal.',
    waiting: 'Waiting',
    sessionEnds: (m: string) => `My session ends in ${m}`,
    sessionEndsText: 'The dev-shell reaches its time limit. The last thing I did:',
    purgeTitle: (d: string) => `/scratch purge on Tuesday ${d}`,
    purgeText: "Research Computing's policy purges /scratch on the first Tuesday of each month. Move to /projects what you can't download again.",
    test: 'discord-drop test',
    testText: 'If you see this card, the webhook works.',
    eta: 'ETA',
    full: 'Full text attached.',
  },
} as const
export type Strings = (typeof STRINGS)[Lang]

export type Attachment = { path: string; name: string }

/** Upload names: the basename, safe for `attachment://`, unique within the card. */
export function attachments(drop: Drop, extra: readonly string[] = []): { image: Attachment | null; files: Attachment[] } {
  const used = new Set<string>()
  const name = (path: string) => {
    const base = (path.split('/').pop() || 'file').replace(/[^A-Za-z0-9._-]+/g, '_').slice(-80) || 'file'
    let n = base
    for (let i = 2; used.has(n); i++) n = `${i}_${base}`
    used.add(n)
    return n
  }
  const image = drop.image ? { path: drop.image, name: name(drop.image) } : null
  return { image, files: [...drop.files, ...extra].map(p => ({ path: p, name: name(p) })) }
}

/** "▰▰▰▰▰▱▱▱▱▱ 52%" */
export function progressBar(p: number, width = 12): string {
  const n = Math.round(Math.max(0, Math.min(1, p)) * width)
  return `${'▰'.repeat(n)}${'▱'.repeat(width - n)} ${Math.round(p * 100)}%`
}

export type CardContext = {
  host: string
  project: string | null
  now: number
  lang: Lang
  image: Attachment | null
}

export type Embed = {
  color: number
  title: string
  url?: string
  description?: string
  fields?: { name: string; value: string; inline: boolean }[]
  author?: { name: string }
  footer: { text: string }
  timestamp: string
  image?: { url: string }
}

/**
 * The embed for a drop, and whether its text had to be cut (the caller then
 * attaches it in full). The total stays under Discord's 6000 characters.
 */
export function card(drop: Drop, ctx: CardContext): { embed: Embed; isCut: boolean } {
  const s = STRINGS[ctx.lang]
  const head: string[] = []
  if (drop.kind === 'progress' && drop.progress !== null) head.push(progressBar(drop.final ? 1 : drop.progress))
  if (drop.eta !== null && !drop.final) head.push(`${s.eta} <t:${Math.round(drop.eta)}:R>`)
  const title = cut(`${ICON[drop.kind]} ${drop.title || cut(drop.text.split('\n')[0] ?? '', 80)}`, LIMIT.title)
  const author = cut(drop.author ?? (ctx.project ? `Claude · ${ctx.project}` : 'Claude'), LIMIT.author)
  const footer = cut(drop.footer ? `${drop.footer} · ${ctx.host}` : `discord-drop · ${ctx.host}`, LIMIT.footer)
  const fields: Field[] = drop.fields.slice(0, LIMIT.fields).map(f => ({ name: cut(f.name, LIMIT.name), value: cut(f.value, LIMIT.value), inline: f.inline }))
  const fixed = title.length + author.length + footer.length + fields.reduce((n, f) => n + f.name.length + f.value.length, 0)
  const room = Math.max(200, Math.min(LIMIT.description, LIMIT.total - fixed - 50))
  const body = [head.join('  ·  '), drop.title ? drop.text : drop.text.split('\n').slice(1).join('\n')].filter(Boolean).join('\n\n')
  const isCut = body.length > room
  const description = isCut ? `${cut(body, room - s.full.length - 6)}\n-# ${s.full}` : body
  const embed: Embed = {
    color: COLOR[drop.kind],
    title,
    ...(drop.url ? { url: drop.url } : {}),
    ...(description ? { description } : {}),
    ...(fields.length ? { fields } : {}),
    author: { name: author },
    footer: { text: footer },
    timestamp: new Date(ctx.now).toISOString(),
    ...(ctx.image ? { image: { url: `attachment://${ctx.image.name}` } } : {}),
  }
  return { embed, isCut }
}

/** The JSON a post carries: the card, its uploads, no pings for @-mentions in the text. */
export function payload(embed: Embed, uploads: readonly Attachment[], isSilent: boolean): string {
  return JSON.stringify({
    embeds: [embed],
    allowed_mentions: { parse: [] },
    ...(isSilent ? { flags: SILENT } : {}),
    ...(uploads.length ? { attachments: uploads.map((u, i) => ({ id: i, filename: u.name })) } : {}),
  })
}

/** Webhook base: the URL without a query or trailing slash. */
export const baseOf = (url: string) => url.trim().replace(/[?#].*$/, '').replace(/\/+$/, '')

/** What `curl -K -` reads on stdin: just the URL. */
export const curlConfig = (url: string) => `url = "${url.replace(/["\\]/g, '')}"\n`

/** curl for a new message: multipart, the card in payload_json, each upload as files[i]. */
export function postArgv(json: string, uploads: readonly Attachment[]): string[] {
  return [
    'curl', '-sS', '--max-time', '60', '-K', '-', '-w', '\n%{http_code}',
    '--form-string', `payload_json=${json}`,
    ...uploads.flatMap((u, i) => ['-F', `files[${i}]=@"${u.path}";filename="${u.name}"`]),
  ]
}

/** curl for an edit of a message the webhook sent: the card as JSON, no uploads. */
export function patchArgv(json: string): string[] {
  return ['curl', '-sS', '--max-time', '30', '-K', '-', '-w', '\n%{http_code}', '-X', 'PATCH', '-H', 'Content-Type: application/json', '--data-raw', json]
}

export const postUrl = (base: string) => `${base}?wait=true`
export const messageUrl = (base: string, id: string) => `${base}/messages/${id}`

/** curl's stdout (body, then the status on its own line) as status and parsed body. */
export function parseCurl(stdout: string): { status: number; body: Record<string, unknown> | null } {
  const i = stdout.lastIndexOf('\n')
  const status = Number(stdout.slice(i + 1).trim()) || 0
  const text = stdout.slice(0, Math.max(0, i)).trim()
  try {
    const body = JSON.parse(text) as unknown
    return { status, body: body && typeof body === 'object' ? (body as Record<string, unknown>) : null }
  } catch {
    return { status, body: null }
  }
}

/** A short, URL-free reason for a failed call. */
export function failure(status: number, body: Record<string, unknown> | null, stderr: string): string {
  const msg = typeof body?.message === 'string' ? body.message : ''
  const why = status ? `HTTP ${status}${msg ? `: ${msg}` : ''}` : stderr.replace(/https?:\/\/\S+/g, '<url>').trim().slice(0, 200) || 'no answer'
  return `discord-drop: Discord refused the card (${why}).`
}

/** The duration field Claude's own cards carry. */
export const tookField = (s: Strings, seconds: number): Field => ({ name: s.took, value: fmtDur(seconds), inline: true })

